// Parse a URL using built-in support, and convert to the legacy format which
// was previously hand-rolled in this file.
//
// TODO document why decodeURIComponent() is required for username & password.

function parseUri(str) {
  const url = new URL(str);
  const uri = {
    host:     url.hostname,
    password: decodeURIComponent(url.password),
    path:     url.pathname,
    port:     url.port,
    protocol: url.protocol.replace(/:$/, ''),
    user:     decodeURIComponent(url.username),
  };

  if (uri.user || uri.password) {
    uri.userInfo = uri.user + ':' + uri.password;
  }

  return uri;
}

export default parseUri;
